// frontend/src/components/Sidebar.jsx
import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import ProfileMenu from "./ProfileMenu";
import DeleteConfirmModal from "./DeleteConfirmModal";
import "./Sidebar.css";

export default function Sidebar({ sessions = [], onLoadSession = () => {}, onNewChat = () => {} }) {
  const [remoteSessions, setRemoteSessions] = useState([]);
  const [loadingDelete, setLoadingDelete] = useState(null);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [toDelete, setToDelete] = useState(null);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    fetch("/api/sessions/list")
      .then((r) => (r.ok ? r.json() : []))
      .then((data) => {
        if (Array.isArray(data)) setRemoteSessions(data);
      })
      .catch(() => setRemoteSessions([]));
  }, []);

  const mergedSessions = React.useMemo(() => {
    const map = new Map();
    (sessions || []).forEach((s) => { if (s && s.id) map.set(String(s.id), s); });
    (remoteSessions || []).forEach((rs) => { if (rs && rs.id && !map.has(String(rs.id))) map.set(String(rs.id), rs); });
    const arr = Array.from(map.values());
    arr.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
    return arr.slice(0, 50);
  }, [sessions, remoteSessions]);

  function handleLoadSession(sess) {
    try { onLoadSession(sess); } catch (e) { console.error(e); }
    navigate("/");
  }

  function handleNewChat() {
    try { onNewChat(); } catch (e) { console.error(e); }
    navigate("/");
  }

  function promptDeleteSession(id, title) {
    setToDelete({ id, title });
    setConfirmOpen(true);
  }

  async function confirmDelete() {
    if (!toDelete) { setConfirmOpen(false); return; }
    const id = toDelete.id;
    setLoadingDelete(id);
    setConfirmOpen(false);
    try {
      const resp = await fetch(`/api/sessions/${encodeURIComponent(id)}`, { method: "DELETE" });
      if (!resp.ok) {
        const txt = await resp.text().catch(() => "");
        throw new Error(txt || "Failed to delete session");
      }
      setRemoteSessions((rs) => rs.filter((r) => String(r.id) !== String(id)));
      // also remove from localStorage
      try {
        const raw = localStorage.getItem("ai_chat_sessions");
        if (raw) {
          const arr = JSON.parse(raw).filter((x) => String(x.id) !== String(id));
          localStorage.setItem("ai_chat_sessions", JSON.stringify(arr));
        }
      } catch (e) {}
    } catch (e) {
      console.error("delete failed", e);
      alert(e.message || "Failed to delete session.");
    } finally {
      setLoadingDelete(null);
      setToDelete(null);
    }
  }

  function shortSummary(s, n = 7) {
    const text = (s?.title && String(s.title).trim()) || (s?.prompt && String(s.prompt).trim()) || "";
    if (!text) return "";
    const words = text.split(/\s+/);
    if (words.length <= n) return text;
    return words.slice(0, n).join(" ") + "...";
  }

  return (
    <>
      <aside className="sidebar" role="navigation" aria-label="Main sidebar">
        <div className="sidebar-inner">
          <button className="btn-new" onClick={handleNewChat} aria-label="Start a new chat">＋ New Chat</button>

          <div className="sidebar-block">
            <div className="sidebar-title">Chat History</div>

            <div className="history-list" aria-live="polite">
              {mergedSessions.length === 0 ? (
                <div className="empty">No saved chats yet</div>
              ) : (
                mergedSessions.map((s) => {
                  const id = s.id;
                  const summ = shortSummary(s, 7);
                  const meta = s.createdAt ? new Date(s.createdAt).toLocaleString() : "";
                  return (
                    <div
                      key={id}
                      className="chat-row"
                      title={s.title || s.prompt || ""}
                      // ensure keyboard accessibility
                      tabIndex={0}
                      onKeyDown={(e) => { if (e.key === "Enter") handleLoadSession(s); }}
                      role="button"
                      aria-label={`Open chat ${summ}`}
                    >
                      <div className="chat-body" onClick={() => handleLoadSession(s)}>
                        <div className="chat-title">{summ}</div>
                        <div className="chat-sub">{meta}</div>
                      </div>

                      <button
                        className="chat-delete"
                        onClick={(ev) => { ev.stopPropagation(); promptDeleteSession(id, s.title || s.prompt); }}
                        aria-label={`Delete chat ${summ}`}
                        title="Delete chat"
                        disabled={loadingDelete === id}
                      >
                        {loadingDelete === id ? "…" : "Delete"}
                      </button>
                    </div>
                  );
                })
              )}
            </div>
          </div>

          <div className="sidebar-block nav-block">
            <div className="sidebar-title">Navigation</div>
            <nav className="nav-list" aria-label="Main navigation">
              <Link to="/flights" className={`nav-link ${location.pathname === "/flights" ? "active" : ""}`}>
                <span className="nav-ico">✈️</span><span className="nav-text">Flight Search</span>
              </Link>

              <Link to="/hotels" className={`nav-link ${location.pathname === "/hotels" ? "active" : ""}`}>
                <span className="nav-ico">🏨</span><span className="nav-text">Hotels & Cuisines</span>
              </Link>

              <Link to="/news" className={`nav-link ${location.pathname === "/news" ? "active" : ""}`}>
                <span className="nav-ico">📰</span><span className="nav-text">Travel News & Blogs</span>
              </Link>
            </nav>
          </div>
        </div>

        <div className="sidebar-footer">
          <ProfileMenu />
        </div>
      </aside>

      <DeleteConfirmModal
        open={confirmOpen}
        title={toDelete?.title || "Delete chat"}
        onCancel={() => setConfirmOpen(false)}
        onConfirm={confirmDelete}
      />
    </>
  );
}
